O0xff8a035ea6c80673f741c2265985ed976a40d390''','\n')) AS entry
), periods AS (
  SELECT k,
    TIMESTAMP_SUB(TIMESTAMP '2026-10-29 20:05:00+00', INTERVAL (7*k) DAY) AS shock,
    TIMESTAMP_SUB(TIMESTAMP '2026-11-01 09:00:00+00', INTERVAL (7*k) DAY) AS reopen
  FROM UNNEST(GENERATE_ARRAY(0,8)) AS k
  UNION ALL
  SELECT k+100,
    TIMESTAMP_SUB(TIMESTAMP '2026-11-01 06:00:00+00', INTERVAL (7*k) DAY),
    TIMESTAMP_SUB(TIMESTAMP '2026-11-01 09:00:00+00', INTERVAL (7*k) DAY)
  FROM UNNEST(GENERATE_ARRAY(0,8)) AS k
), transfers AS (
  SELECT t.block_timestamp AS ts, t.transaction_hash AS tx, t.event_index AS idx,
    t.from_address AS src, t.to_address AS dst, t.address AS token,
    SAFE_CAST(t.quantity AS BIGNUMERIC) AS amount, d.role AS dst_role, s.role AS src_role
  FROM `bigquery-public-data.goog_blockchain_ethereum_mainnet_us.token_transfers` t
  LEFT JOIN seeds d ON d.wallet = t.to_address
  LEFT JOIN seeds s ON s.wallet = t.from_address
  WHERE t.block_timestamp >= TIMESTAMP '2026-08-05 20:05:00+00'
    AND t.block_timestamp < TIMESTAMP '2026-11-09 09:00:00+00'
    AND t.address IN ('0xdac17f958d2ee523a2206206994597c13d831ec7','0xa0b86991c6218b36c1d19d4a2e9eb0ce3606eb48')
    AND SAFE_CAST(t.quantity AS BIGNUMERIC) > 0 AND NOT COALESCE(t.removed,FALSE)
    AND t.from_address != t.to_address
    AND t.from_address != '0x0000000000000000000000000000000000000000'
    AND t.to_address != '0x0000000000000000000000000000000000000000'
    AND t.transaction_hash IS NOT NULL AND t.event_index IS NOT NULL
), legacy_matches AS (
  SELECT ts AS swept, dst_role,
    COUNTIF(dst_role IS DISTINCT FROM 'F') OVER prior AS n,
    LAST_VALUE(IF(dst_role IS DISTINCT FROM 'F',STRUCT(ts,tx,idx,src,dst,amount),NULL)
      IGNORE NULLS) OVER prior AS deposit
  FROM transfers
  WHERE src_role IS DISTINCT FROM 'F'
  WINDOW prior AS (
    PARTITION BY IF(dst_role='F',src,dst),token,amount
    ORDER BY UNIX_MICROS(ts) RANGE BETWEEN 86400000000 PRECEDING AND 1 PRECEDING
  )
), legacy_paths AS (
  SELECT w.k, w.shock, w.reopen, p.deposit.*
  FROM legacy_matches p JOIN periods w
    ON p.deposit.ts >= TIMESTAMP_SUB(w.shock,INTERVAL 28 DAY) AND p.swept < w.shock
  WHERE p.dst_role='F' AND p.n=1
  QUALIFY COUNT(*) OVER (PARTITION BY w.k,p.deposit.tx,p.deposit.idx)=1
), cohort AS (
  SELECT k, shock, reopen, src AS sender, COUNT(*) AS pre_count, SUM(amount)/1000000 AS pre_amount,
    COUNT(DISTINCT DATE(ts)) AS pre_days, TIMESTAMP_DIFF(shock,MAX(ts),HOUR) AS recency_h
  FROM legacy_paths
  GROUP BY k, shock, reopen, sender
  HAVING pre_days>=2 AND MAX(ts)>=TIMESTAMP_SUB(shock,INTERVAL 7 DAY)
), own_destinations AS (
  SELECT DISTINCT k, src AS sender, dst FROM legacy_paths
), broad_matches AS (
  SELECT ts AS swept, tx AS sweep_tx, idx AS sweep_idx, dst_role AS role,
    COUNTIF(dst_role IS NULL) OVER prior AS n,
    LAST_VALUE(IF(dst_role IS NULL,STRUCT(ts,tx,idx,src,dst,token,amount),NULL)
      IGNORE NULLS) OVER prior AS deposit
  FROM transfers
  WHERE src_role IS NULL
  WINDOW prior AS (
    PARTITION BY IF(dst_role IS NULL,dst,src),token,amount
    ORDER BY UNIX_MICROS(ts) RANGE BETWEEN 86400000000 PRECEDING AND 1 PRECEDING
  )
), broad_paths AS (
  SELECT deposit.*, swept, sweep_tx, sweep_idx, role,
    CASE WHEN role IN ('B','F','N') THEN 'B' ELSE role END AS venue
  FROM broad_matches
  WHERE role IS NOT NULL AND n=1
), prior_paths AS (
  SELECT w.k, p.dst, p.venue, p.ts, p.src, p.swept, p.amount
  FROM broad_paths p JOIN periods w
    ON p.ts>=TIMESTAMP_SUB(w.shock,INTERVAL 28 DAY) AND p.swept<w.shock
  WHERE p.role!='N'
  QUALIFY COUNT(*) OVER (PARTITION BY w.k,p.tx,p.idx)=1
), prior_labels AS (
  SELECT k,dst,MIN(p.venue) AS venue,
    COUNT(DISTINCT DATE(ts)) AS match_days, COUNT(DISTINCT src) AS deposit_senders,
    COUNT(DISTINCT IF(TIMESTAMP_DIFF(swept,ts,SECOND)<=21600,DATE(ts),NULL)) AS fast_days
  FROM prior_paths AS p
  GROUP BY k,dst
  HAVING COUNT(DISTINCT p.venue)=1 AND COUNT(DISTINCT DATE(ts))>=2
), excluded AS (
  SELECT CONCAT('0x',TO_HEX(SUBSTR(payload,pos,20))) AS sender
  FROM (SELECT FROM_BASE64(REPLACE('''AAAAAAAA1Xdf93Ic77gJevYuUt0AAAAAAE49VigjTxi5dwQeUkJlHwAAv39OS3+yMV/G1dD4hUyR3/HYAAO1ql4w6X/MWWu10POnUlXgjU4ABJylU35cIHVy
